def gen(rng):
    def fmt(cap, ops):
        return f'{cap} {len(ops)}\n' + '\n'.join(ops)
    def rnd(cap, q, keyrange, valmax, w):
        ops = []
        for _ in range(q):
            r = rng.random()
            k = rng.randint(0, keyrange)
            if r < w[0]:
                ops.append(f'get {k}')
            elif r < w[0] + w[1]:
                ops.append(f'put {k} {rng.randint(0, valmax)}')
            elif r < w[0] + w[1] + w[2]:
                ops.append(f'delete {k}')
            else:
                ops.append('last')
        ops.append('last')
        return fmt(cap, ops)
